namespace LSE.AutoCADElectrical.Librarian;
// Maps catalog parts (MANUFACTURER + CATALOG, what a schematic symbol carries in MFG/CAT) to footprint drawings in
// footprint_lookup.mdb: one table per manufacturer, a plain row (no ASSEMBLYCODE) per catalog number, BLKNAM = full DWG path.
// Load is read only. Execute is the only writer used for stand-alone mapping: validate everything, take the library lock,
// back the MDB up, write, read back, report; on any failure the MDB is restored from the backup before the exception is rethrown.
public static class FootprintMappingService{
 public const string Unmapped="Unmapped",Mapped="Mapped",MissingDrawing="Missing drawing",BlockName="Block name";
 public static string Status(string blk){if(blk.Trim().Length==0)return Unmapped;if(!(blk.Contains('\\')||blk.Contains('/')))return BlockName;return File.Exists(blk)?Mapped:MissingDrawing;}
 static void RequireStores(AppSettings s){if(s.CatalogPath.Trim().Length==0||!File.Exists(s.CatalogPath))throw new FileNotFoundException("Catalog database was not found (LSELIBRARYSETTINGS).",s.CatalogPath);if(s.FootprintLookupPath.Trim().Length==0||!File.Exists(s.FootprintLookupPath))throw new FileNotFoundException("footprint_lookup.mdb was not found (LSELIBRARYSETTINGS).",s.FootprintLookupPath);}
 // Every LSE part in default_cat.mdb with its current footprint_lookup state. Read only.
 public static List<FootprintMapRow> Load(AppSettings s,bool withSymbols=false){RequireStores(s);var cat=new CatalogService(s.CatalogPath);var parts=cat.ReadParts(CatalogTransactionService.PartColumn(s));var syms=withSymbols?cat.ReadSymbols(CatalogTransactionService.PartColumn(s)):new Dictionary<string,string>();var map=new FootprintLookupService(s.FootprintLookupPath).ReadMappings(parts.Select(p=>(p.Manufacturer,p.Catalog)));
  return parts.Select(p=>{map.TryGetValue(FootprintLookupService.Key(p.Manufacturer,p.Catalog),out var b);b??="";return new FootprintMapRow{Family=p.Table,Manufacturer=p.Manufacturer,Catalog=p.Catalog,PartNumber=p.Part,Description=p.Description,BlkNam=b,Status=Status(b),Symbol=syms.TryGetValue(p.Table+"|"+p.Part,out var sy)?sy:""};}).OrderBy(r=>r.Manufacturer,StringComparer.OrdinalIgnoreCase).ThenBy(r=>r.Catalog,StringComparer.OrdinalIgnoreCase).ToList();}
 // Current BLKNAM of the plain row, "" when there is none. Read only.
 public static string Existing(AppSettings s,string manufacturer,string catalog){RequireStores(s);var fp=new FootprintLookupService(s.FootprintLookupPath);string? t=fp.ResolveTable(manufacturer);return t is null?"":fp.FindPlain(t,catalog.Trim()).BlkNam;}
 // Returns the full footprint path that will be stored. Nothing is written.
 public static string Validate(AppSettings s,FootprintMapRequest q){RequireStores(s);
  if(s.IconMenuFolder.Trim().Length==0||!Directory.Exists(s.IconMenuFolder))throw new InvalidOperationException("The icon menu folder is not set or missing (LSELIBRARYSETTINGS); the library lock file lives there.");if(s.BackupFolder.Trim().Length==0)throw new InvalidOperationException("The backup folder is not set (LSELIBRARYSETTINGS).");
  if(q.Manufacturer.Trim().Length==0||q.Catalog.Trim().Length==0)throw new InvalidOperationException("MANUFACTURER and CATALOG are required.");if(q.Manufacturer.Trim().Length>24)throw new InvalidOperationException("MANUFACTURER is limited to 24 characters.");if(q.Catalog.Trim().Length>60)throw new InvalidOperationException("CATALOG is limited to 60 characters.");Ace.ValidateTable(q.Manufacturer.Trim());
  if(q.Footprint.Trim().Length==0)throw new InvalidOperationException("Choose the footprint drawing.");string full;try{full=Path.GetFullPath(q.Footprint.Trim());}catch{throw new InvalidOperationException("The footprint path is not valid: "+q.Footprint);}
  if(!Path.GetExtension(full).Equals(".dwg",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("The footprint must be a .dwg drawing: "+full);if(!File.Exists(full))throw new FileNotFoundException("The footprint drawing does not exist.",full);
  if(!(NamingService.Inside(full,s.FootprintLibraryFolder)||NamingService.Inside(full,s.StockFootprintLibraryFolder)))throw new InvalidOperationException("The footprint must live in the footprint library ("+s.FootprintLibraryFolder+") or the stock footprint library ("+s.StockFootprintLibraryFolder+"): "+full);
  if(full.Length>255)throw new InvalidOperationException("Footprint path is longer than 255 characters (BLKNAM limit): "+full);return full;}
 public static FootprintMapResult Execute(AppSettings s,FootprintMapRequest q,Action<string>? progress=null)=>Execute(s,new[]{q},progress);
 // One backup, one lock, all-or-nothing for the whole batch.
 public static FootprintMapResult Execute(AppSettings s,IReadOnlyList<FootprintMapRequest> qs,Action<string>? progress=null){
  if(qs.Count==0)throw new InvalidOperationException("Nothing to map.");var paths=qs.Select(q=>Validate(s,q)).ToList();var dupe=qs.GroupBy(q=>FootprintLookupService.Key(q.Manufacturer,q.Catalog),StringComparer.OrdinalIgnoreCase).FirstOrDefault(g=>g.Count()>1);if(dupe is not null)throw new InvalidOperationException("The same part is listed twice: "+dupe.Key);
  var fp=new FootprintLookupService(s.FootprintLookupPath);
  List<(int Index,bool Write,string Previous)> Decide(){var plan=new List<(int,bool,string)>();for(int i=0;i<qs.Count;i++){string? t=fp.ResolveTable(qs[i].Manufacturer);string prev=t is null?"":fp.FindPlain(t,qs[i].Catalog.Trim()).BlkNam;
    if(prev.Length>0&&prev.Equals(paths[i],StringComparison.OrdinalIgnoreCase)){plan.Add((i,false,prev));continue;}
    if(prev.Length>0&&!qs[i].Overwrite)throw new InvalidOperationException($"[{qs[i].Manufacturer.Trim()}] {qs[i].Catalog.Trim()} is already mapped to {prev}. Nothing was changed; confirm the overwrite to replace it.");plan.Add((i,true,prev));}return plan;}
  var first=Decide();var result=new FootprintMapResult{Unchanged=first.Count(p=>!p.Write)};if(!first.Any(p=>p.Write)){result.Report="Every part is already mapped to the chosen footprint; nothing was written.";progress?.Invoke(result.Report);return result;}
  string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss")+"_footprintmap";string backup=Path.Combine(s.BackupFolder,stamp);int suffix=0;while(Directory.Exists(backup))backup=Path.Combine(s.BackupFolder,stamp+"_"+(++suffix));Directory.CreateDirectory(backup);result.BackupFolder=backup;
  var log=new List<string>{$"Started: {DateTime.Now:s} by {Environment.UserName}@{Environment.MachineName}",$"Footprint lookup: {s.FootprintLookupPath}",$"Backup folder: {backup}"};void Log(string m){log.Add(m);progress?.Invoke(m);}foreach(string m in log)progress?.Invoke(m);
  string mdbBackup=Path.Combine(backup,Path.GetFileName(s.FootprintLookupPath));using var gate=LibraryLock.Acquire(s.IconMenuFolder,log);File.Copy(s.FootprintLookupPath,mdbBackup,true);Log("Backup: PASS");bool written=false;
  try{var plan=Decide();for(int i=0;i<qs.Count;i++)Log((plan[i].Write?(plan[i].Previous.Length>0?"Remap  ":"Map    "):"Same   ")+qs[i].Summary.Replace(qs[i].Footprint,paths[i])+(plan[i].Previous.Length>0&&plan[i].Write?" (was "+plan[i].Previous+")":""));
   foreach(var (index,write,_) in plan){if(!write)continue;var q=qs[index];string t=q.Manufacturer.Trim();written=true;fp.EnsureTable(t);t=fp.ResolveTable(t)??t;fp.SetMapping(t,q.Catalog.Trim(),paths[index],q.Description);result.Written++;}
   foreach(var (index,write,_) in plan){if(!write)continue;var q=qs[index];string t=fp.ResolveTable(q.Manufacturer)??throw new InvalidOperationException("Read-back failed: the manufacturer table is missing after the write.");var (rows,blk)=fp.FindPlain(t,q.Catalog.Trim());if(rows==0||!blk.Equals(paths[index],StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException($"Read-back of the footprint lookup row failed for [{q.Manufacturer.Trim()}] {q.Catalog.Trim()}.");}
   Log($"Footprint lookup read-back: PASS ({result.Written} written, {result.Unchanged} already correct)");Log("Status: SUCCESS");try{File.WriteAllLines(Path.Combine(backup,"FootprintMapReport.txt"),log);}catch{}result.Report=string.Join(Environment.NewLine,log);return result;}
  catch(Exception ex){Log("ERROR: "+ex.Message);try{File.Copy(mdbBackup,s.FootprintLookupPath,true);Log(written?"Footprint lookup rollback: PASS":"Footprint lookup rollback: PASS (nothing had been written)");}catch(Exception rx){Log("Footprint lookup rollback: FAILED "+rx.Message);}try{File.WriteAllLines(Path.Combine(backup,"FootprintMapReport.txt"),log);}catch{}throw;}
 }
}
